UPDATE t_order
SET state = '3', update_datetime = NOW()
WHERE order_id = #{orderId}
  AND sender_id = #{userId}
  AND state = '0'

mapper.select:
SELECT o.order_id, u_sender.username AS sender_name, u_getter.username AS getter_name, o.title, o.content, o.type, o.deposit, o.sender_price, o.state, o.user_complete, o.auditor_complete, o.release_datetime, o.end_datetime, o.complete_datetime, o.pay_state, o.deposit_state FROM t_order o LEFT JOIN t_user u_sender ON o.sender_id = u_sender.user_id LEFT JOIN t_user u_getter ON o.getter_id = u_getter.user_id
o.state = '0' AND o.pay_state = '1'
and o.type=#{type}
and o.sender_price >=#{minPrice}
and o.sender_price <=#{maxPrice}
ORDER BY o.sender_price ${sort}

SELECT o.order_id, u_sender.username AS sender_name, u_getter.username AS getter_name, o.title, o.content, o.type, o.deposit, o.sender_price, o.state, o.user_complete, o.auditor_complete, o.release_datetime, o.end_datetime, o.complete_datetime, o.pay_state, o.deposit_state FROM t_order o LEFT JOIN t_user u_sender ON o.sender_id = u_sender.user_id LEFT JOIN t_user u_getter ON o.getter_id = u_getter.user_id
o.sender_id = #{userId}
AND o.state = #{state}
ORDER BY o.release_datetime DESC

SELECT o.order_id, u_sender.username AS sender_name, u_getter.username AS getter_name, o.title, o.content, o.type, o.deposit, o.sender_price, o.state, o.user_complete, o.auditor_complete, o.release_datetime, o.end_datetime, o.complete_datetime, o.pay_state, o.deposit_state FROM t_order o LEFT JOIN t_user u_sender ON o.sender_id = u_sender.user_id LEFT JOIN t_user u_getter ON o.getter_id = u_getter.user_id
getter_id=#{userId}
and o.state=#{state}
ORDER BY release_datetime desc

mapper.update:
update t_order
update_datetime=now(), title = #{order.title}, content = #{order.content}, type = #{order.type}, sender_price = #{order.senderPrice}, deposit = #{order.deposit}, end_datetime = #{order.endDatetime},
where order_id=#{order.orderId} and sender_id=#{userId}
